import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { ObjectLink } from "@/components/ui/object-link"
import { StateTag } from "@/components/ui/state-tag"

/**
 * The first thing a person sees about a problem: where, what, what it costs, one action.
 * `new` carries a signal-colour edge until it is opened.
 */
export interface AlertCardProps {
  /** e.g. "Cooling · issue" */
  area: string
  /** Shown top right while open, e.g. "+14% power". */
  delta?: string
  object: string
  objectHref: string
  /** The rest of the headline after the object name. */
  headline: string
  /** One line in money or time, e.g. "About ¥250 a day above normal". */
  cost: string
  state?: "new" | "open" | "investigating" | "resolved"
  onInvestigate?: () => void
  className?: string
}

export function AlertCard({ area, delta, object, objectHref, headline, cost, state = "new", onInvestigate, className }: AlertCardProps) {
  const done = state === "resolved"
  return (
    <article
      data-slot="alert-card"
      data-state={state}
      className={cn(
        "grid gap-2.5 bg-[var(--gc-glass)] px-5 py-[18px] shadow-[inset_0_1px_0_var(--gc-edge-hi),var(--gc-drop)] backdrop-blur-[24px] transition-[box-shadow,opacity,transform] duration-300 ease-gc hover:-translate-y-0.5 motion-reduce:hover:translate-y-0",
        state === "new" && "shadow-[inset_3px_0_0_var(--gc-accent),inset_0_1px_0_var(--gc-edge-hi),var(--gc-drop)]",
        done && "opacity-70",
        className
      )}
    >
      <div className="flex items-center gap-3">
        <span className="font-mono text-[11px] uppercase tracking-[0.05em] text-muted-foreground">{area}</span>
        <span className="ml-auto">
          {state === "investigating" ? <StateTag state="investigating" /> : done ? <StateTag state="resolved" /> : delta ? <StateTag state="issue">{delta}</StateTag> : null}
        </span>
      </div>
      <h3 className="m-0 text-lg font-normal leading-[25px]">
        <ObjectLink href={objectHref}>{object}</ObjectLink> {headline}
      </h3>
      <span className="text-[13px] text-muted-foreground">{cost}</span>
      {(state === "new" || state === "open") && (
        <div className="mt-1.5 border-t border-border pt-3.5">
          <Button onClick={onInvestigate}>Investigate</Button>
        </div>
      )}
    </article>
  )
}
